import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        Map<String, String> forRequirement = Map.of(
                "REST_API", "spring-boot-starter-web",
                "DB_CRUD", "spring-boot-starter-data-jpa",
                "LOGIN", "spring-boot-starter-security",
                "NIGHTLY_IMPORT", "spring-boot-starter-batch",
                "OPS", "spring-boot-starter-actuator");

        int r = Integer.parseInt(sc.nextLine().trim());
        Set<String> needed = new TreeSet<>();
        for (int i = 0; i < r; i++) {
            String starter = forRequirement.get(sc.nextLine().trim());
            if (starter != null) needed.add(starter);
        }
        int n = Integer.parseInt(sc.nextLine().trim());
        Set<String> declared = new TreeSet<>();
        for (int i = 0; i < n; i++) {
            declared.add(between(sc.nextLine(), "<artifactId>", "</artifactId>"));
        }

        List<String> report = new ArrayList<>();
        for (String starter : needed) {
            if (!declared.contains(starter)) report.add("MISSING " + starter);
        }
        for (String starter : declared) {
            if (!starter.startsWith("spring-boot-starter-")) continue;
            if (starter.equals("spring-boot-starter-test")) continue;   // テストは常に必要
            if (!needed.contains(starter)) report.add("UNUSED " + starter);
        }
        if (report.isEmpty()) {
            System.out.println("OK");
        } else {
            Collections.sort(report);
            report.forEach(System.out::println);
        }
    }

    static String between(String line, String open, String close) {
        int from = line.indexOf(open) + open.length();
        return line.substring(from, line.indexOf(close, from)).trim();
    }
}

