import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        Map<String, String> smallest = Map.of(
                "SERVICE_RULE", "none",
                "JSON_VALIDATION", "@WebMvcTest",
                "REPOSITORY_QUERY", "@DataJpaTest",
                "FULL_FLOW", "@SpringBootTest");
        Map<String, Integer> width = Map.of(
                "none", 0, "@WebMvcTest", 1, "@DataJpaTest", 1, "@SpringBootTest", 2);

        int n = Integer.parseInt(sc.nextLine().trim());
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            String name = parts[0], actual = parts[1], target = parts[2];
            String expected = smallest.get(target);
            String verdict;
            if (actual.equals(expected)) {
                verdict = "OK";
            } else if (width.get(actual) > width.get(expected)) {
                verdict = "TOO_WIDE " + expected;
            } else if (width.get(actual) < width.get(expected)) {
                verdict = "TOO_NARROW " + expected;
            } else {
                verdict = "WRONG_SLICE " + expected;      // 広さは同じで切り口が違う
            }
            System.out.println(name + " " + verdict);
        }
    }
}

