import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        Map<String, String> env = readPairs(sc);
        Map<String, String> file = readPairs(sc);
        String name = sc.nextLine();
        boolean available = Boolean.parseBoolean(sc.nextLine().trim());

        if (!available) {
            System.out.println("503 SERVICE_UNAVAILABLE");
            return;
        }
        String trimmed = name.trim();
        if (trimmed.isEmpty()) {
            System.out.println("400 NAME_REQUIRED");
            return;
        }
        String prefix = env.get("APP_GREETING_PREFIX");
        if (prefix == null) prefix = file.get("app.greeting.prefix");
        if (prefix == null) prefix = "Hello";
        System.out.println("200 " + prefix + ", " + trimmed);
    }

    static Map<String, String> readPairs(Scanner sc) {
        int count = Integer.parseInt(sc.nextLine().trim());
        Map<String, String> map = new HashMap<>();
        for (int i = 0; i < count; i++) {
            String line = sc.nextLine();
            int eq = line.indexOf('=');
            map.put(line.substring(0, eq).trim(), line.substring(eq + 1).trim());
        }
        return map;
    }
}

