import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        String environment = sc.nextLine().trim();
        int n = Integer.parseInt(sc.nextLine().trim());
        String key = "management.endpoints.web.exposure.include=";
        String include = "";
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine().trim();
            if (line.startsWith(key)) include = line.substring(key.length()).trim();
        }
        List<String> all = List.of("health", "info", "metrics", "loggers", "env");
        Set<String> exposed = new TreeSet<>();
        if (include.equals("*")) {
            exposed.addAll(all);
        } else if (!include.isEmpty()) {
            for (String name : include.split(",")) {
                String trimmed = name.trim();
                if (!trimmed.isEmpty()) exposed.add(trimmed);
            }
        }
        boolean violation = false;
        for (String name : exposed) {
            String verdict = switch (name) {
                case "health", "info" -> "ALLOW";
                case "metrics" -> environment.equals("internal") ? "ALLOW" : "DENY";
                case "loggers" -> environment.equals("internal") ? "ADMIN_ONLY" : "DENY";
                default -> "DENY";
            };
            if (verdict.equals("DENY")) violation = true;
            System.out.println(name + ":" + verdict);
        }
        System.out.println(violation ? "VIOLATION" : "OK");
    }
}
